            AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("By the definition of sigma, its value is 1 when r is positive and -1 otherwise. In either branch multiplying it by itself gives 1. The nonpositive branch includes r=0, so no nonzero hypothesis is needed for this identity."))), DescribeRole.Theorem),
        Describe.Lean(DescribeId.Create("statement1"), DeclarationHandle.Create("D5/S3/Quantum/Algebra/StateApproximation/UniformSignedSquare.sigma_abs"),
