            AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Self-adjointness of d makes pi(d) equal to its adjoint. apply_norm_sq_eq_inner_adjoint_right and multiplicativity express norm(pi(d)Omega) squared as the real part of the moment of d squared. The hypothesis hm identifies that moment with beta(square d), and Real.sqrt_sq removes the square using nonnegativity of the norm."))), DescribeRole.Theorem),
        Describe.Lean(DescribeId.Create("statement7"), DeclarationHandle.Create("D5/S3/Quantum/Algebra/StateApproximation/UniformSignedSquare.signed_endpoint"),
